[data-component="session-turn"] {
  --sticky-header-height: calc(var(--session-title-height, 0px) + 24px);
  height: 100%;
  min-height: 0;
  min-width: 0;
  display: flex;
  align-items: flex-start;
  justify-content: flex-start;

  .ui-session-turn-content {
    flex-grow: 1;
    width: 100%;
    height: 100%;
    min-width: 0;
    overflow-y: auto;
    scrollbar-width: none;
  }

  .ui-session-turn-content::-webkit-scrollbar {
    display: none;
  }

  [data-slot="session-turn-message-container"] {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    align-self: stretch;
    min-width: 0;
    gap: 0px;
    overflow-anchor: none;
  }

  [data-slot="session-turn-message-content"] {
    margin-top: 0;
    width: 100%;
    min-width: 0;
    max-width: 100%;
  }

  [data-slot="session-turn-compaction"] {
    width: 100%;
    min-width: 0;
    align-self: stretch;
  }

  [data-slot="session-turn-thinking"] {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
    width: 100%;
    min-width: 0;
    color: var(--text-weak);
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-20);
    min-height: 20px;

    .ui-spinner {
      width: 16px;
      height: 16px;
    }
  }

  .ui-text-reveal.session-turn-thinking-heading {
    flex: 1 1 auto;
    min-width: 0;
    color: var(--text-weaker);
    font-weight: var(--font-weight-regular);
  }

  .error-card {
    color: var(--v2-text-text-base);
    max-height: 240px;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    word-break: break-word;
    overflow-y: auto;
  }

  [data-slot="session-turn-assistant-content"] {
    width: 100%;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-self: stretch;
    gap: 12px;
  }

  [data-slot="session-turn-diffs"] {
    width: 100%;
    min-width: 0;
  }

  [data-slot="session-turn-diffs-header"] {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-top: 4px;
    padding-bottom: 12px;
    position: sticky;
    top: var(--sticky-accordion-top, 0px);
    z-index: 20;
    background-color: var(--v2-background-bg-base);
    height: 44px;
  }

  [data-slot="session-turn-diffs-label"] {
    font-variant-numeric: tabular-nums;
    color: var(--text-strong);
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-large);
  }

  [data-slot="session-turn-diffs-toggle"] {
    color: var(--text-interactive-base);
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-regular);
    line-height: var(--line-height-large);
    cursor: pointer;
    opacity: 0;
    transition: opacity 0.15s ease;
    margin-left: 4px;
  }

  [data-component="session-turn-diffs-group"]:hover [data-slot="session-turn-diffs-toggle"] {
    opacity: 1;
  }

  [data-component="session-turn-diffs-group"][data-show-all] [data-slot="session-turn-diffs-toggle"] {
    opacity: 1;
  }

  [data-slot="session-turn-diffs-more"] {
    color: var(--text-weak);
    font-family: var(--font-family-sans);
    font-size: var(--font-size-small);
    line-height: var(--line-height-large);
    margin-top: 12px;
    padding: 0 0 6px;
    cursor: pointer;
    transition: color 0.15s ease;

    &:hover {
      color: var(--text-link-base);
    }
  }

  [data-component="session-turn-diffs-content"] {
    padding-top: 0px;
    display: flex;
    flex-direction: column;
  }

  [data-slot="session-turn-diff-trigger"] {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    width: 100%;
    min-width: 0;
  }

  [data-slot="session-turn-diff-path"] {
    display: flex;
    flex-grow: 1;
    min-width: 0;

    font-family: var(--font-family-sans);
    font-size: var(--font-size-small);
    line-height: var(--line-height-large);
  }

  [data-slot="session-turn-diff-directory"] {
    color: var(--text-base);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    direction: rtl;
    text-align: left;
  }

  [data-slot="session-turn-diff-filename"] {
    min-width: 0;
    color: var(--text-strong);
    font-weight: var(--font-weight-medium);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="session-turn-diff-meta"] {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    gap: 10px;
  }

  [data-slot="session-turn-diff-chevron"] {
    display: inline-flex;
    color: var(--icon-weaker);
    transform: rotate(-90deg);
    transition: transform 0.15s ease;
  }

  [data-slot="accordion-item"][data-expanded] [data-slot="session-turn-diff-chevron"] {
    transform: rotate(0deg);
  }

  [data-slot="session-turn-diff-view"] {
    background-color: var(--surface-inset-base);
    width: 100%;
    min-width: 0;
    overflow-y: auto;
    overflow-x: hidden;
    scrollbar-width: none;
    -ms-overflow-style: none;
  }

  [data-slot="session-turn-diff-view"]::-webkit-scrollbar {
    display: none;
  }
}

body:not([data-new-layout]) [data-component="session-turn"] {
  .error-card {
    color: var(--text-base);
  }

  [data-slot="session-turn-diffs-header"] {
    background-color: var(--background-stronger);
  }
}

[data-slot="session-turn-list"] {
  gap: 24px;
}
/*
 * WorkGroup (T4) — collapsed run of bash/edit/write/apply_patch/web tools folded to
 * one muted line. Header follows the activity-row voice; expanded body scrolls at 224px
 * with edge fades when it overflows and dims its member rows (depth by dimming, D§8 #6).
 */
[data-component="work-group-trigger"] {
  width: 100%;
  min-height: 32px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
  cursor: default;

  /* Same uniform dim + 14px icon as the tool rows, so a group header and a tool row
     read as the same voice rather than two different greys. */
  color: var(--text-weak);

  [data-slot="work-group-icon"] {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 14px;
    height: 14px;
    color: inherit;
  }

  [data-slot="work-group-icon"] .ui-icon {
    width: 14px;
    height: 14px;
    color: inherit;
  }

  .ui-work-group-summary {
    min-width: 0;
    flex: 0 1 auto;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-family: var(--font-family-sans);
    font-size: var(--font-size-base);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-large);
    color: var(--text-weak);
    transition: color 0.15s ease;
  }

  .ui-collapsible-arrow {
    color: var(--icon-weaker);
    cursor: pointer;
  }
}

@media (hover: hover) {
  [data-slot="collapsible-trigger"]:hover
    [data-component="work-group-trigger"]
    .ui-work-group-summary {
    color: var(--text-strong);
  }
}

[data-slot="collapsible-trigger"]:focus-visible
  [data-component="work-group-trigger"]
  .ui-work-group-summary {
  color: var(--text-strong);
}

.ui-work-group-list {
  padding-left: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 224px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}

/* Edge fades only when the body actually overflows (data-overflowing). */
.ui-work-group-list[data-overflowing="true"] {
  mask-image: linear-gradient(
    to bottom,
    transparent,
    black 24px,
    black calc(100% - 24px),
    transparent
  );
}

@media (hover: hover) {
  .ui-work-group-list:hover {
    scrollbar-color: var(--border-weak-base) transparent;
  }
}

/* Nested member rows: dimmer, icon-less. */
[data-component="work-group-list"] .ui-basic-tool-tool-leading-icon,
[data-component="work-group-list"] [data-slot="context-tool-group-title"] .ui-collapsible-arrow {
  display: none;
}

