    opacity: 0;
    transition: opacity 0.15s ease;
    z-index: 1;
  }

  [data-component="markdown-code"]:hover [data-slot="markdown-copy-button"],
  [data-slot="markdown-copy-button"]:focus-within {
    opacity: 1;
  }

  [data-slot="markdown-rich-controls"] {
    position: absolute;
    top: 2px;
    right: 0;
    display: flex;
    align-items: center;
    gap: 2px;
    height: 20px;
    padding: 0;
    border: 0;
    background: transparent;
    box-shadow: none;
    opacity: 0;
    transition: opacity 150ms ease;
    z-index: 2;
  }

  [data-markdown-rich]:hover > [data-slot="markdown-rich-controls"],
  [data-slot="markdown-rich-controls"]:focus-within {
    opacity: 1;
  }

  [data-slot="markdown-rich-controls"] > [data-slot="markdown-copy-button"] {
    position: static;
    opacity: 1;
  }

  [data-slot="markdown-view-button"] {
    display: contents;
  }

  [data-slot="markdown-rich-controls"] .ui-icon-button-v2 {
    width: 20px;
    height: 20px;
    background: transparent;
  }

  [data-slot="markdown-rich-controls"] .ui-icon-button-v2:is(:hover, :active, :focus-visible) {
    background: transparent;
    color: var(--v2-icon-icon-base);
  }

  [data-slot="mermaid-render-button"] {
    position: absolute;
    inset: 50% auto auto 50%;
    transform: translate(-50%, -50%);
    min-height: 28px;
    padding: 0 10px;
    border: 0.5px solid var(--v2-border-border-base, var(--border-weak-base));
    border-radius: var(--radius-md);
    background: var(--v2-background-bg-base, var(--surface-raised-base));
    color: var(--v2-text-text-base, var(--text-strong));
    cursor: pointer;
    z-index: 1;
  }

  [data-slot="mermaid-render-button"]:hover,
  [data-slot="mermaid-render-button"]:focus-visible {
    background: var(--v2-background-bg-hover, var(--surface-inset-base));
    outline: none;
  }

  [data-slot="markdown-copy-button"] [data-check-icon] {
