    if (part.type !== "text" || !part.synthetic) return undefined
    const next = readCommentMetadata(part.metadata) ?? parseCommentNote(part.text)
    if (!next) return undefined
    return {
      path: next.path,
      comment: next.comment,
      selection: next.selection
